	/**
	 * Default Constructor
	 */
    public BillingProfileService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new BillingProfileEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(BillingProfileRepository.class) );
		this.validator		= applicationContext.getBean(BillingProfileValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		BillingProfile
	 */
		public BillingProfile createBillingProfile( CreateBillingProfileCommand command ) {

		BillingProfile entity = new BillingProfile();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setBillingProfileId( command.getBillingProfileId() );
            entity.setBillingName( command.getBillingName() );
            entity.setTaxId( command.getTaxId() );
            entity.setBillingAddress( command.getBillingAddress() );
            entity.setPaymentTerms( command.getPaymentTerms() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of BillingProfile {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateBillingProfileCommand
	 * @return		BillingProfile
	 */
	public BillingProfile updateBillingProfile( UpdateBillingProfileCommand command ) {

		BillingProfile entity = new BillingProfile();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setBillingProfileId( command.getBillingProfileId() );
            entity.setBillingName( command.getBillingName() );
            entity.setTaxId( command.getTaxId() );
            entity.setBillingAddress( command.getBillingAddress() );
            entity.setAdvertiser( command.getAdvertiser() );
            entity.setPaymentMethods( command.getPaymentMethods() );
            entity.setAdAccounts( command.getAdAccounts() );
            entity.setPaymentTerms( command.getPaymentTerms() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of BillingProfile {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteBillingProfileCommand
	 */
	public void delete( DeleteBillingProfileCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getBillingProfileId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of BillingProfile {0} ", id );

	}

	/**
	 * Method to retrieve the BillingProfile via BillingProfileFetchOneSummary
	 * @param 	summary BillingProfileFetchOneSummary
	 * @return 	BillingProfileFetchOneResponse
	 */
	public BillingProfile getBillingProfile( BillingProfileFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "BillingProfileFetchOneSummary arg cannot be null" );

		BillingProfile entity = null;
		UUID id = summary.getBillingProfileId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a BillingProfile using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all BillingProfiles
	 *
	 * @return 	List<BillingProfile>
	 */
    public List<BillingProfile> getAllBillingProfile() {
		List<BillingProfile> list = projector.findAll( new FindAllBillingProfileQuery() );
		return list;
	}

	/**
	 * assign Advertiser on BillingProfile
	 * @param		command AssignAdvertiserToBillingProfileCommand
	 */
	public void assignAdvertiser( AssignAdvertiserToBillingProfileCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignAdvertiser(command.getBillingProfileId(), command.getAssignment());

	}

